"""Real Konva native state (generated by services/engine/scripts/gen_fixtures.js) judged by the
independent Python verifier. Same procedure; only the private move-frame drift differs."""

import json
import pathlib

from open_apprentice.evaluation.verifier import verify_gap_row

FX = json.loads(pathlib.Path("tests/integration/fixtures/konva_gap_row.json").read_text())
TASK = {
    "canvas": {"width": 800, "height": 500},
    "selected_ids": ["a", "b", "c"],
    "parameters": {"gap_px": 24, "left_px": 80, "top_px": 120},
}


def test_real_konva_nested_gap_row_passes_without_drift():
    r = verify_gap_row(FX["ok_local_frame"]["initial"], FX["ok_local_frame"]["final"], TASK)
    assert r.passed, [(c.name, c.detail) for c in r.checks if not c.passed]


def test_same_procedure_fails_under_unannounced_world_frame_drift():
    d = FX["drifted_world_frame"]
    r = verify_gap_row(d["initial"], d["final"], TASK)
    assert not r.passed
    assert {"edge_gaps_match", "left_edge_matches", "top_aligned"} & set(r.failed())
